let transferFilters={sellerClub:'all',position:'all',ageGroup:'all',primaryMin:0,potentialMin:0,sort:'position',query:'',shortlistOnly:false,affordableOnly:false},recruitmentReview=null,recruitmentReturn=null,recruitmentBusy=false,recruitmentPreviewToken=0;
let transferQueryTimer=null,transferQueryComposing=false;
function applyTransferQuery(focus=false){
 clearTimeout(transferQueryTimer);transferQueryTimer=null;if(typeof view!=='undefined'&&view!=='market')return;
 const input=$('transfer-query'),caret=input?.selectionStart;transferFilters.query=input?.value||'';renderMarket();
 if(focus){const next=$('transfer-query');next?.focus({preventScroll:true});if(Number.isInteger(caret))next?.setSelectionRange?.(caret,caret);}
}
function transferCandidates(){
 const host=$('transfer-search-panel'),m=TransferPlans.search(season,transferFilters,outgoingChoices);if(!host)return m.rows.map(r=>F.market.find(p=>p.identity===r.identity));const esc=escapeText;
 const options=(items,value)=>items.map(([v,t])=>'<option value="'+v+'"'+(String(v)===String(value)?' selected':'')+'>'+t+'</option>').join('');
 host.innerHTML='<section class="transfer-search" aria-labelledby="transfer-search-title"><div class="panel-heading"><h2 id="transfer-search-title">스카우트 영입 목록</h2><span role="status">후보 '+m.rows.length+' / '+m.total+'명 · 관심 '+m.shortlistCount+'명</span></div><div class="transfer-filter-grid"><label>상대 구단<select id="transfer-seller-club">'+options([['all','모든 상대 구단'],...m.clubs.map(c=>[c.id,c.name])],m.filters.sellerClub)+'</select></label><label>포지션<select id="transfer-position">'+options([['all','전체 포지션'],['GK','GK · 골키퍼'],['DEF','DEF · 수비수'],['MID','MID · 미드필더'],['FW','FW · 공격수']],m.filters.position)+'</select></label><label>나이<select id="transfer-age">'+options([['all','모든 나이'],['u21','21세 이하'],['22-25','22–25세'],['26-29','26–29세'],['30+','30세 이상']],m.filters.ageGroup)+'</select></label><label>주요 능력<select id="transfer-primary-min">'+options([[0,'제한 없음'],[70,'70 이상'],[75,'75 이상'],[80,'80 이상'],[85,'85 이상']],m.filters.primaryMin)+'</select></label><label>성장 한계<select id="transfer-potential-min">'+options([[0,'제한 없음'],[85,'85 이상'],[90,'90 이상'],[95,'95 이상']],m.filters.potentialMin)+'</select></label><label>정렬<select id="transfer-sort">'+options([['position','포지션 순'],['club','구단별'],['primary','현재 능력 높은 순'],['potential','성장 한계 높은 순'],['age','어린 선수 순'],['cost','영입 지출 낮은 순'],['corner','코너 지표 높은 순'],['freeKick','프리킥 지표 높은 순'],['target','공중볼 지표 높은 순']],m.filters.sort)+'</select></label><form id="transfer-query-form"><label>이름·구단명 (선택)<input type="search" id="transfer-query" maxlength="60" value="'+esc(m.filters.query)+'" placeholder="이름이나 구단명으로 찾기"></label><button type="submit" class="secondary">검색</button></form></div><div class="transfer-filter-toggles"><button type="button" id="transfer-shortlist-only" aria-pressed="'+m.filters.shortlistOnly+'" class="secondary">관심 선수만</button><button type="button" id="transfer-affordable-only" aria-pressed="'+m.filters.affordableOnly+'" class="secondary">현재 자금 안에서</button><button type="button" id="transfer-filter-reset" class="text-button">전체 후보 보기</button></div><p>필터를 바꾸면 바로 적용됩니다. 검색어를 비워도 구단·포지션·나이·능력 기준으로 찾을 수 있습니다. 주요 능력은 해당 포지션 핵심 능력, 성장 한계는 육성 상한입니다. 지출은 선택한 방출 선수와 수수료를 반영합니다.</p>'+(m.rows.length?'':'<p class="transfer-empty" role="status">조건에 맞는 후보가 없습니다. 구단이나 기준을 바꾸거나 필터를 초기화하세요.</p>')+'</section>';
 const input=$('transfer-query');input.value=m.filters.query;
 const redraw=id=>{clearTimeout(transferQueryTimer);transferQueryTimer=null;transferFilters.query=$('transfer-query').value;renderMarket();$(id)?.focus({preventScroll:true});};
 for(const [id,key,numeric] of [['transfer-seller-club','sellerClub'],['transfer-position','position'],['transfer-age','ageGroup'],['transfer-primary-min','primaryMin',true],['transfer-potential-min','potentialMin',true],['transfer-sort','sort']])$(id).onchange=e=>{transferFilters[key]=numeric?Number(e.target.value):e.target.value;redraw(id);};
 input.oncompositionstart=()=>{transferQueryComposing=true;clearTimeout(transferQueryTimer);};input.oncompositionend=()=>{transferQueryComposing=false;applyTransferQuery(true);};
 input.oninput=e=>{if(transferQueryComposing||e?.isComposing)return;clearTimeout(transferQueryTimer);if(!input.value){applyTransferQuery(true);return;}transferQueryTimer=setTimeout(()=>applyTransferQuery(document.activeElement===$('transfer-query')),180);};
 input.onsearch=()=>applyTransferQuery(true);
 $('transfer-query-form').onsubmit=e=>{e.preventDefault();transferQueryComposing=false;applyTransferQuery(true);};
 $('transfer-shortlist-only').onclick=()=>{transferFilters.shortlistOnly=!transferFilters.shortlistOnly;redraw('transfer-shortlist-only');};$('transfer-affordable-only').onclick=()=>{transferFilters.affordableOnly=!transferFilters.affordableOnly;redraw('transfer-affordable-only');};
 $('transfer-filter-reset').onclick=()=>{clearTimeout(transferQueryTimer);transferQueryTimer=null;transferQueryComposing=false;transferFilters={sellerClub:'all',position:'all',ageGroup:'all',primaryMin:0,potentialMin:0,sort:'position',query:'',shortlistOnly:false,affordableOnly:false};renderMarket();$('transfer-seller-club')?.focus({preventScroll:true});};
 return m.rows.map(r=>{const person=F.market.find(p=>p.identity===r.identity);return person?{...person,sellerClub:{id:r.sellerClubId,name:r.sellerClubName,short:r.sellerClubShort}}:null;}).filter(Boolean);
}
function transferShortlistMarkup(identity){const on=!!season.transferPlans?.shortlist.includes(identity);return '<button type="button" class="secondary transfer-shortlist" data-shortlist="'+escapeText(identity)+'" aria-pressed="'+on+'">'+(on?'★ 관심 선수':'☆ 관심에 추가')+'</button>';}
function bindTransferShortlist(host){host.querySelectorAll('[data-shortlist]').forEach(button=>button.onclick=()=>{const identity=button.dataset.shortlist;action(()=>{season=TransferPlans.toggle(season,identity);state=season.match;});const next=$('market-overview').querySelector('[data-shortlist="'+identity+'"]');(next||$('transfer-shortlist-only'))?.focus({preventScroll:true});});}
function transferSetPieceComparisonMarkup(m){if(m.incoming.pos==='GK')return '';return '<section class="recruitment-set-pieces" aria-label="영입 전후 세트피스 비교"><h3>세트피스 역할 비교</h3><dl>'+Object.entries(F.setPieceRoleNames).map(([role,label])=>{const before=m.outgoing.setPieces[role],after=m.incoming.setPieces[role],delta=after-before;return '<div><dt>'+({corner:'코너',freeKick:'프리킥',target:'공중볼'}[role])+'</dt><dd>'+before+' → '+after+' <span>('+ (delta>0?'+':'')+delta+')</span></dd></div>';}).join('')+'</dl><p>현재 능력으로 계산한 키커·타깃 지표이며 득점 확률은 아닙니다. 영입 후 선발에 넣고 전술에서 담당을 정하세요.</p>'+(m.releasedSetPieces.length?'<p>떠나는 선수의 '+m.releasedSetPieces.map(role=>F.setPieceRoleNames[role]).join(' · ')+' 우선 지정은 해제됩니다.</p>':'')+'</section>';}
function closeRecruitmentReview(){if(recruitmentBusy)return;recruitmentPreviewToken++;const dialog=$('recruitment-dialog');dialog.close();dialog.removeAttribute('aria-busy');recruitmentReview=null;recruitmentReturn?.focus?.({preventScroll:true});}
function openRecruitmentReview(identity,slot){
 if(recruitmentBusy)return;const dialog=$('recruitment-dialog');if(!dialog)return;const token=++recruitmentPreviewToken;recruitmentReturn=document.activeElement;recruitmentReview=null;
 dialog.innerHTML='<div class="recruitment-head"><h2 id="recruitment-title">영입 조건 확인 중</h2><button type="button" id="close-recruitment" class="secondary" aria-label="영입 검토 닫기">×</button></div><div class="recruitment-body"><p id="recruitment-status" role="status" aria-live="polite">선수 비교와 계약 비용을 확인하는 중…</p></div>';dialog.setAttribute('aria-busy','true');$('close-recruitment').onclick=closeRecruitmentReview;dialog.oncancel=e=>{e.preventDefault();closeRecruitmentReview();};if(!dialog.open)dialog.showModal();$('close-recruitment').focus({preventScroll:true});
 requestAnimationFrame(()=>setTimeout(()=>renderRecruitmentReview(identity,slot,token),0));
}
function renderRecruitmentReview(identity,slot,token){
 if(token!==recruitmentPreviewToken||recruitmentBusy)return;const dialog=$('recruitment-dialog');if(!dialog?.open)return;let error='';try{recruitmentReview=TransferPlans.preview(season,identity,slot);}catch(e){error=e.message;}const m=recruitmentReview,esc=escapeText;
 dialog.innerHTML='<div class="recruitment-head"><div><span class="eyebrow">계약 검토</span><h2 id="recruitment-title">'+(m?.academy?'1군 등록 최종 확인':'영입 최종 확인')+'</h2></div><button type="button" id="close-recruitment" class="secondary" aria-label="영입 검토 닫기">×</button></div><div class="recruitment-body">'+(m?'<p class="recruitment-warning"><strong>'+esc(m.outgoing.name)+'</strong> 선수가 구단을 떠납니다. 이 선수의 성장과 경험은 새 선수에게 이어지지 않습니다. 확정 전에 교환 대상을 확인하세요.</p><div class="recruitment-people"><article><span>떠나는 선수 · '+m.outgoing.pos+'</span><h3>'+esc(m.outgoing.name)+'</h3><p>주요 능력 '+m.outgoing.primary+' · 성장 한계 '+m.outgoing.potential+'</p><small>누적 출전 경험 '+m.outgoing.xp.toLocaleString('ko-KR')+'분</small></article><article><span>합류하는 선수 · '+m.incoming.pos+'</span><h3>'+esc(m.incoming.name)+'</h3><p>주요 능력 '+m.incoming.primary+' · 성장 한계 '+m.incoming.potential+'</p><small>출전 경험 0 · 체력 100</small></article></div>'+transferSetPieceComparisonMarkup(m)+'<dl class="recruitment-terms"><div><dt>'+(m.quote.cost<0?'구단에 돌아오는 자금':'영입 지출 · 수수료 포함')+'</dt><dd>'+moneyLabel(m.quote.cost)+'</dd></div><div><dt>영입 후 자금</dt><dd>'+moneyLabel(m.quote.balanceAfter)+'</dd></div><div><dt>선수 주급 변화</dt><dd>'+signedMoney(m.quote.wageChange)+'</dd></div></dl><p class="recruitment-note">이번 주 영입 기회 1회를 사용합니다. 새 선수는 '+(m.starting?'선발에':'벤치에')+' 등록됩니다.'+(m.lineupChanged?' 출전 가능 인원을 맞추며 선발이 조정됩니다.':'')+'</p><div class="recruitment-actions"><button type="button" id="cancel-recruitment" class="secondary">다시 비교하기</button><button type="button" id="confirm-recruitment" class="primary">이 조건으로 '+(m.academy?'1군 등록':'영입')+' 확정</button></div>':'<p class="recruitment-warning">'+esc(error)+'</p>')+'<p id="recruitment-status" role="status" aria-live="polite"></p></div>';
 const close=closeRecruitmentReview;$('close-recruitment').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};if(m){$('cancel-recruitment').onclick=close;$('confirm-recruitment').onclick=confirmRecruitmentReview;}dialog.removeAttribute('aria-busy');$('close-recruitment').focus({preventScroll:true});
}
function confirmRecruitmentReview(){
 if(recruitmentBusy||!recruitmentReview)return;const m=recruitmentReview,dialog=$('recruitment-dialog'),button=$('confirm-recruitment');recruitmentBusy=true;button.disabled=true;$('cancel-recruitment').disabled=true;$('close-recruitment').disabled=true;$('recruitment-status').textContent='계약을 등록하고 구단을 저장하는 중…';dialog.setAttribute('aria-busy','true');
 requestAnimationFrame(()=>setTimeout(()=>{try{const next=TransferPlans.confirm(season,m.identity,m.slot,m.fingerprint);season=next;state=season.match;selected=null;save();recruitmentReview=null;dialog.close();render();const notice=$('notice');notice.innerHTML=escapeText(m.incoming.name+' '+(m.academy?'1군 등록':'영입')+' 완료 · '+m.outgoing.name+' 이적'+(canSave?'':' · 저장 공간을 확인해 주세요.'))+'<button type="button" id="review-signing" class="secondary">'+(m.starting?'프리킥·코너 담당 확인':'선발·교체 계획 확인')+'</button>';notice.hidden=false;$('review-signing').onclick=()=>{const player=Object.values(state?.players||{}).find(p=>p.identity===m.identity);if(!player)return;setView('match');selected=state.lineup.includes(player.id)?player.id:null;openMatchPopup(state.phase==='prep'&&state.lineup.includes(player.id)?'tactics':'roster',$('review-signing'));};const control=$(view+'-pane')?.querySelector('[data-player-detail="'+m.identity+'"]');(control||$('transfer-position')||recruitmentReturn)?.focus?.({preventScroll:true});}catch(e){$('recruitment-status').textContent=e.message;button.disabled=true;$('cancel-recruitment').disabled=false;$('close-recruitment').disabled=false;}finally{recruitmentBusy=false;dialog.removeAttribute('aria-busy');}},0));
}
